#include <stdio.h>
#include <stdlib.h>

#define MAXN 50005

typedef struct {
    int to;
    int next;
} Edge;

int head[MAXN];
Edge edges[2 * MAXN];
int edge_cnt = 0;

void add_edge(int u, int v) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;

    edges[edge_cnt].to = u;
    edges[edge_cnt].next = head[v];
    head[v] = edge_cnt++;
}

int dist[MAXN];
int parent[MAXN];
int queue[MAXN];

int bfs(int start, int n) {
    for (int i = 1; i <= n; i++) {
        dist[i] = -1;
        parent[i] = 0;
    }

    int q_start = 0, q_end = 0;
    queue[q_end++] = start;
    dist[start] = 0;

    int farthest = start;

    while (q_start < q_end) {
        int u = queue[q_start++];
        if (dist[u] > dist[farthest]) {
            farthest = u;
        }

        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent[v] = u;
                queue[q_end++] = v;
            }
        }
    }

    return farthest;
}

int count_at_depth(int start, int forbidden, int target_depth) {
    int q_start = 0, q_end = 0;
    queue[q_end++] = start;

    // We can use a local dist array or just pair of (u, d)
    // Since start is a tree component, let's use queue with depths
    static int d_queue[MAXN];
    d_queue[0] = 1; // start is at depth 1 from the center

    // To avoid visiting forbidden (the center), forbidden is blocked.
    // Also we need to avoid going backwards in tree traversal.
    // Since it's a tree, parent is enough.
    static int p_queue[MAXN];
    p_queue[0] = forbidden;

    int count = 0;

    while (q_start < q_end) {
        int u = queue[q_start];
        int d = d_queue[q_start];
        int p = p_queue[q_start];
        q_start++;

        if (d == target_depth) {
            count++;
            continue; // No need to explore deeper
        }

        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (v != p) {
                queue[q_end] = v;
                d_queue[q_end] = d + 1;
                p_queue[q_end] = u;
                q_end++;
            }
        }
    }

    return count;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 1; i <= n; i++) {
        head[i] = -1;
    }

    for (int i = 0; i < n - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(u, v);
    }

    int node_a = bfs(1, n);
    int node_b = bfs(node_a, n);

    int diameter = dist[node_b];

    // Reconstruct path from node_a to node_b
    static int path[MAXN];
    int curr = node_b;
    int path_len = 0;
    while (curr != 0) {
        path[path_len++] = curr;
        curr = parent[curr];
    }
    // path has node_b at index 0 and node_a at index path_len - 1
    // Reverse it so path[0] = node_a, path[diameter] = node_b
    for (int i = 0; i < path_len / 2; i++) {
        int tmp = path[i];
        path[i] = path[path_len - 1 - i];
        path[path_len - 1 - i] = tmp;
    }

    long long ways = 0;

    if (diameter % 2 == 0) {
        int center = path[diameter / 2];
        int target = diameter / 2;

        long long sum = 0;
        long long sum_sq = 0;

        for (int e = head[center]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            long long cnt = count_at_depth(v, center, target);
            sum += cnt;
            sum_sq += cnt * cnt;
        }

        ways = (sum * sum - sum_sq) / 2;
    } else {
        int c1 = path[(diameter - 1) / 2];
        int c2 = path[(diameter + 1) / 2];
        int target = (diameter + 1) / 2;

        long long cnt1 = count_at_depth(c1, c2, target);
        long long cnt2 = count_at_depth(c2, c1, target);

        ways = cnt1 * cnt2;
    }

    printf("%d\n", diameter + 1);
    printf("%lld\n", ways);

    return 0;
}
